#!/usr/bin/env python3
"""
Round 103b (culprits), 28 September 2026. Round 102b must be applied first.

The drug underworld map in clearly different colours; governments' birth-rate
policies; who turned holidays into sales and who made holidays to displace
others; who makes fake science, named; plainer research integrity rows; one
line per place in crowded lists; headings dragged like rows; slavery's cases
and enforcement apart, with enforcement in every country; the anti-slavery
trackers built again.

Run from the repository root (the apply-patch workflow does).
"""
import base64, pathlib, subprocess, sys, tempfile

DIFF = ''
NOTE = '## Round 103b (28 September)\n\nNeeds round 102b (runs after it by name). Tiles patch round103b_tiles.py beside it.\n\n- capture_map: keepColour + recolour (keys without "#") by the page\'s kind\n  colours into distinct reds, pinks, browns, bone, greys, blues and teals, with\n  a key. sitemap recolour takes a colour alone or [colour, size].\n- site_research_integrity: typeTitles (plain kind names), recolour, standout\n  {keep:true} (ring in each place\'s own colour). research_makers (geojsonlive,\n  tiles research_makers.py reads both tabs of the page) under Science.\n- fertility_policy (countrycat, tiles fertility_policy.py, UN World\n  Population Policies 2021 reproductive health module; column found by heading)\n  under Suppression > Sex.\n- holiday_culprits (geojsonlive, tiles holidays/culprits.geojson, 21 entries\n  compiled 28 September from the Wikipedia articles cited in each) under\n  Holidays.\n- "N places here" lists one line each (flex, nowrap, ellipsis), 440 px wide,\n  scrolling past 340 px.\n- Headings draggable: grip-h on every heading line (mouse can drag the line);\n  moveHeading inserts above/below another heading or row.\n- Slavery: Routes and Cases and enforcement apart; slavery_convicted_world,\n  slavery_detected_world (UNODC via tiles slavery_world.py) and\n  slavery_cbp_world (US CBP WROs and Findings, country label points);\n  slavery_enforcement retitled for what it is (Brazil\'s register).\n- pipeline/shapes/registry.json: slavery_trackers no longer retired (it 404ed);\n  the tiles patch also carries a fresh build of it.\n- Script version app.js?v=994.\n\n'
HEAD = "## Round 103b (28 September)"


def git(*a, check=True):
    return subprocess.run(["git", *a], capture_output=True, text=True, check=check)


def main():
    root = pathlib.Path(".")
    if not (root / "map" / "app.js").exists():
        sys.exit("round103b: run from the culprits repository root")
    if "## Round 102b" not in (root / "HANDOFF.md").read_text(encoding="utf-8"):
        sys.exit("round103b: round 102b must be applied first")
    with tempfile.NamedTemporaryFile("wb", suffix=".diff", delete=False) as f:
        f.write(base64.b64decode(DIFF))
        path = f.name
    if git("apply", "--check", "-R", "--binary", path, check=False).returncode == 0:
        print("round103b: already applied")
    else:
        r = git("apply", "--3way", "--binary", path, check=False)
        if r.returncode != 0:
            sys.exit("round103b: the diff did not apply:\n" + r.stdout + r.stderr)
        print("round103b: applied")
    h = root / "HANDOFF.md"
    text = h.read_text(encoding="utf-8")
    if HEAD not in text:
        at = text.index("## Round 102b")
        h.write_text(text[:at] + NOTE + "\n" + text[at:], encoding="utf-8")


if __name__ == "__main__":
    main()
